import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';

const root = path.resolve(import.meta.dirname, '../..');
const read = name => fs.readFileSync(path.resolve(root, name));
const sha = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const json = name => JSON.parse(read(name).toString('utf8').replace(/^\uFEFF/, ''));
const reportName = 'docs/evidence/a-owner-frozen-gate-current-20261026-r1.json';
const run = json(reportName);
assert.equal(run.kind, 'd_owner_frozen_baseline_gate_mock_regression.v1');
assert.equal(run.error, null);
for (const field of ['inputs_stable', 'owner_removed', 'real_registered_baseline_parser_executed']) assert.equal(run[field], true, field);
for (const field of ['real_snapshot_copy_executed', 'Go_or_builds_run', 'SSH_or_SQL_executed', 'dependencies_installed', 'production_approved']) assert.equal(run[field], false, field);
assert.equal(run.cases.length, 14);
assert.equal(path.dirname(run.owner).toLowerCase(), root.toLowerCase());
assert.match(path.basename(run.owner), /^\.tmp-d-index-cache-[a-f0-9]{32}$/);
assert.equal(fs.existsSync(run.owner), false);
for (const pin of run.input_pins) assert.equal(sha(read(pin.path)), pin.sha256, 'Current mock input drift: ' + pin.path);
const oldName = 'docs/evidence/a-owner-frozen-gate-independent-20261026.json';
const old = json(oldName);
const shape = item => ({name: item.name, mutation: item.snapshot_mutation, fault: item.fault, expected_dispatch: item.expected_mock_dispatch, succeeded: item.invocation_succeeded, dispatched: item.dispatch_mock_calls, validated: item.validation_mock_calls});
assert.deepEqual(run.cases.map(shape), old.cases.map(shape), 'Current gate no longer preserves all historical controls');
for (const item of run.cases) {
  assert.equal(item.runner_owner_absent, true);
  assert.equal(item.invocation_succeeded, item.expected_mock_dispatch);
  assert.equal(item.dispatch_mock_calls, Number(item.expected_mock_dispatch));
  assert.equal(item.validation_mock_calls, Number(item.expected_mock_dispatch));
  assert.equal(path.dirname(item.log.path).toLowerCase(), path.join(root, 'docs/evidence').toLowerCase());
  assert.equal(sha(read(item.log.path)), item.log.sha256);
  const log = read(item.log.path).toString('utf8');
  if (item.snapshot_mutation === 'ordinary' && item.name.includes('rejected')) assert.match(log, /ordinary_source_changed_requires_reviewed_baseline/);
  if (item.expected_mock_dispatch && item.name !== 'predecessor_ready_then_retry_new_source_reaches_dispatch' && !item.name.startsWith('local_')) assert.match(log, /LOCAL_PASS owner-baseline-frozen=yes/);
}
const wrapper = 'scripts/system-backup-d-config-writer-validation.ps1', entry = 'docs/evidence/a-download-owner-role-retest-20261021.ps1';
const w = read(wrapper).toString('utf8'), e = read(entry).toString('utf8');
const capture = w.indexOf('$writerSnapshot=New-AConfigProofSourceSnapshot');
const gate = w.indexOf('if($RequireReviewedOwnerBaseline){');
const dispatch = w.indexOf("& (Join-Path $writerFrozen 'scripts/system-backup-a-evidence-dispatch.test.ps1')");
assert.ok(capture >= 0 && gate > capture && dispatch > gate);
assert.ok(w.slice(gate, dispatch).includes('($writerSnapshot|ConvertTo-Json'));
assert.ok(!w.slice(gate, dispatch).includes('Get-DIndexSourceFiles'));
assert.match(e, /RequireReviewedOwnerBaseline\s*=\s*\$true/);
const nativeTextName = 'docs/evidence/a-owner-frozen-gate-current-20261026-r1.txt';
const text = read(nativeTextName).toString('utf8');
assert.equal((text.match(/^PASS \S+ mock_dispatch=[01] actual_Go=no actual_SSH=no\r?$/gm) || []).length, 14);
assert.match(text, /FROZEN_GATE_REGRESSION_PASS cases=14 owner_removed=yes Go=no SSH=no/);
const historicalName = 'docs/evidence/a-owner-frozen-baseline-gate-reviewed-20261026.json';
const historical = json(historicalName);
assert.equal(historical.independent_outer_exit, 1);
assert.equal(historical.D_corrected_driver_native_exit, 0);
const result = {kind: 'a_owner_current_frozen_gate_review.v1', status: 'accepted_exact_current_mock_gate_not_owner_baseline', native_report: reportName, native_report_sha256: sha(read(reportName)), native_log: nativeTextName, native_log_sha256: sha(read(nativeTextName)), native_outer_exit: 0, cases: run.cases.map(shape), current_input_pins: run.input_pins, historical_reference: historicalName, historical_reference_sha256: sha(read(historicalName)), historical_inline_outer_exit_preserved: 1, historical_whole_script_pin_not_reused: true, frozen_snapshot_checked_before_dispatch: true, live_tree_not_rescanned_for_frozen_gate: true, owner_absent: true, actual_snapshot_copy_performed: false, actual_Go_SSH_SQL_executed: false, current_owner_baseline_ready: false, actual_owner_eleven_accepted: false, production_approved: false, dependencies_installed: false, goal_complete: false};
const output = path.join(root, 'docs/evidence/a-owner-frozen-gate-current-reviewed-20261026-r1.json');
assert.ok(process.argv.length <= 3 && (!process.argv[2] || ['--write', '--check'].includes(process.argv[2])));
if (process.argv[2] === '--write') fs.writeFileSync(output, JSON.stringify(result, null, 2) + '\n', {flag: 'wx'});
if (process.argv[2] === '--check') assert.deepEqual(JSON.parse(fs.readFileSync(output, 'utf8')), result);
process.stdout.write(JSON.stringify({status: result.status, cases: run.cases.length, owner_absent: true, actual_Go_SSH_SQL_executed: false, current_owner_baseline_ready: false}) + '\n');
